CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003102631_InitialCreate') THEN
    CREATE TABLE "ExternalParkingLots" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(200) NOT NULL,
        "Address" character varying(500) NOT NULL,
        "City" character varying(100),
        "Latitude" double precision NOT NULL,
        "Longitude" double precision NOT NULL,
        "ReferencePricePerHour" numeric(18,2),
        "OpeningHoursText" character varying(200),
        "Source" character varying(200),
        "ImportedByUserId" integer NOT NULL,
        "IsDeleted" boolean NOT NULL,
        "DeletedAtUtc" timestamp with time zone,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_ExternalParkingLots" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003102631_InitialCreate') THEN
    CREATE TABLE "OutboxMessages" (
        "Id" uuid NOT NULL,
        "EventType" character varying(200) NOT NULL,
        "PayloadJson" text NOT NULL,
        "OccurredAtUtc" timestamp with time zone NOT NULL,
        "ProcessedAtUtc" timestamp with time zone,
        "AttemptCount" integer NOT NULL,
        "LastError" character varying(2000),
        CONSTRAINT "PK_OutboxMessages" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003102631_InitialCreate') THEN
    CREATE TABLE "ParkingLots" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "OwnerProfileId" integer NOT NULL,
        "Name" character varying(200) NOT NULL,
        "Address" character varying(500) NOT NULL,
        "City" character varying(100) NOT NULL,
        "District" character varying(100),
        "Description" character varying(2000),
        "HotlinePhone" character varying(20),
        "CoverImageUrl" character varying(512),
        "Latitude" double precision NOT NULL,
        "Longitude" double precision NOT NULL,
        "TotalSlots" integer NOT NULL,
        "AvailableSlots" integer NOT NULL,
        "MaxHeightCm" integer NOT NULL,
        "OpenTime" time without time zone NOT NULL,
        "CloseTime" time without time zone NOT NULL,
        "Status" character varying(40) NOT NULL,
        "IntegrationTier" character varying(40) NOT NULL,
        "RatingAverage" numeric(3,2) NOT NULL,
        "RatingCount" integer NOT NULL,
        "IsDeleted" boolean NOT NULL,
        "DeletedAtUtc" timestamp with time zone,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_ParkingLots" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_ParkingLots_Latitude" CHECK ("Latitude" BETWEEN -90 AND 90),
        CONSTRAINT "CK_ParkingLots_Longitude" CHECK ("Longitude" BETWEEN -180 AND 180),
        CONSTRAINT "CK_ParkingLots_Slots" CHECK ("AvailableSlots" >= 0 AND "AvailableSlots" <= "TotalSlots")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261003102631_InitialCreate') THEN
    CREATE TABLE "ClosureSchedules" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "ParkingLotId" integer NOT NULL,
        "TargetType" character varying(40) NOT NULL,
        "TargetId" integer NOT NULL,
        "StartsAtUtc" timestamp with time zone NOT NULL,
        "EndsAtUtc" timestamp with time zone,
        "Reason" character varying(500) NOT NULL,
        "IsEmergency" boolean NOT NULL,
        "AffectedBookingsNotified" boolean NOT NULL,
        "CreatedByUserId" integer NOT NULL,
        "CancelledAtUtc" timestamp with time zone,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_ClosureSchedules" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_ClosureSchedules_Period" CHECK ("EndsAtUtc" IS NULL OR "EndsAtUtc" > "StartsAtUtc"),
        CONSTRAINT "FK_ClosureSchedules_ParkingLots_ParkingLotId" FOREIGN KEY ("ParkingLotId") REFERENCES "ParkingLots" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

