        "UpdatedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_KybApplications" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_KybApplications_ParkingLots_ParkingLotId" FOREIGN KEY ("ParkingLotId") REFERENCES "ParkingLots" ("Id") ON DELETE RESTRICT
